     * @throws PropelException
     */
    public function getDependencias($criteria = null, PropelPDO $con = null)
    {
        $partial = $this->collDependenciasPartial && !$this->isNew();
        if (null === $this->collDependencias || null !== $criteria  || $partial) {
            if ($this->isNew() && null === $this->collDependencias) {
                // return empty collection
                $this->initDependencias();
            } else {
                $collDependencias = DependenciaQuery::create(null, $criteria)
                    ->filterByEntidad($this)
                    ->find($con);
                if (null !== $criteria) {
                    if (false !== $this->collDependenciasPartial && count($collDependencias)) {
                      $this->initDependencias(false);

                      foreach ($collDependencias as $obj) {
                        if (false == $this->collDependencias->contains($obj)) {
