        if (!in_array($l, $this->collDependencias->getArrayCopy(), true)) { // only add it if the **same** object is not already associated
            $this->doAddDependencia($l);

            if ($this->dependenciasScheduledForDeletion and $this->dependenciasScheduledForDeletion->contains($l)) {
                $this->dependenciasScheduledForDeletion->remove($this->dependenciasScheduledForDeletion->search($l));
